	@Test
	void lmdbCascadesComposesOrFilterValuesAndExistsJoinForDistinctAggregateWithFallbackPolicy(@TempDir File dataDir)
			throws Exception {
		LmdbStore store = new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,ospc,psoc,posc").setSketchEstimatorEnabled(false));
		store.init();
		ValueFactory vf = SimpleValueFactory.getInstance();
		String namespace = "http://example.com/theme/medical/";
		IRI code = vf.createIRI(namespace, "code");
		IRI condition = vf.createIRI(namespace, "hasCondition");
		IRI observation = vf.createIRI(namespace, "hasObservation");
		IRI handledBy = vf.createIRI(namespace, "handledBy");
		IRI encounterType = vf.createIRI(namespace, "Encounter");
		IRI urgentType = vf.createIRI(namespace, "UrgentEncounter");
		try (NotifyingSailConnection connection = store.getConnection()) {
			connection.begin();
			// The two finite codes select eight of 1,024 encounters. Only four have observations. The real
			// page counts give the finite anchor a selective lookup advantage over an unbound code scan; no
			// synopsis or learned feedback is needed to choose the composed plan.
			for (int index = 0; index < 1_024; index++) {
				IRI encounter = vf.createIRI("urn:composition:enc:" + index);
				IRI primary = vf.createIRI("urn:composition:cond:" + index);
				Value diagnosis = vf.createLiteral(index < 8 ? "DX-20" + index % 2 : "Unselected " + index);
				connection.addStatement(encounter, RDF.TYPE, encounterType);
				connection.addStatement(primary, code, diagnosis);
				connection.addStatement(encounter, condition, primary);
				if (index < 8) {
					IRI duplicate = vf.createIRI("urn:composition:duplicate-cond:" + index);
					connection.addStatement(duplicate, code, diagnosis);
					connection.addStatement(encounter, condition, duplicate);
				}
				if (index < 4) {
					connection.addStatement(encounter, RDF.TYPE, urgentType);
					for (int duplicate = 0; duplicate < 2; duplicate++) {
						connection.addStatement(encounter, observation,
								vf.createIRI("urn:composition:obs:" + index + ":" + duplicate));
					}
				}
				// Both matched OPTIONAL duplicates and unmatched rows are present among finite-code inputs.
				if (index != 3) {
					for (int duplicate = 0; duplicate < 3; duplicate++) {
						connection.addStatement(encounter, handledBy,
								vf.createIRI("urn:composition:practitioner:" + duplicate));
					}
				}
			}
			connection.commit();
			assertNull(store.getBackingStore().getSketchBasedJoinEstimator());
			TripleSource tripleSource = new TripleSource() {

				@Override
				public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
						Value object, Resource... contexts) {
					return connection.getStatements(subject, predicate, object, false, contexts);
				}

				@Override
				public ValueFactory getValueFactory() {
					return vf;
				}
			};
			Function<TupleExpr, List<BindingSet>> evaluate = expression -> {
				List<BindingSet> rows = new ArrayList<>();
				try (CloseableIteration<BindingSet> result = new StrictEvaluationStrategy(tripleSource, null)
						.precompile(expression)
						.evaluate(EmptyBindingSet.getInstance())) {
					while (result.hasNext()) {
						rows.add(result.next());
					}
				}
				return rows;
			};
			for (String types : List.of("?enc a <http://example.com/theme/medical/Encounter> .", """
					{ ?enc a <http://example.com/theme/medical/Encounter> }
					UNION { ?enc a <http://example.com/theme/medical/UrgentEncounter> }
					""")) {
				StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(tripleSource, null);
				TupleExpr tupleExpr = parseTupleExpr("""
						SELECT (COUNT(DISTINCT ?enc) AS ?count) WHERE {
						  ?cond <http://example.com/theme/medical/code> ?code .
						  ?enc <http://example.com/theme/medical/hasCondition> ?cond .
						  %s
						  OPTIONAL {
						    ?enc <http://example.com/theme/medical/handledBy> ?practitioner .
						  }
						  FILTER EXISTS {
						    ?enc <http://example.com/theme/medical/hasObservation> ?obs .
						  }
						  FILTER(?code = "DX-200" || ?code = "DX-201")
						}
						""".formatted(types));
				List<BindingSet> expected = evaluate.apply(tupleExpr.clone());
				assertEquals(1, expected.size());
				assertEquals("4", expected.get(0).getValue("count").stringValue());
				// This manual optimizer traversal starts with the complete DEFAULT-domain fixture query,
				// bypassing the native connection's usual pipeline entry adapter.
				PlanningGraphDomains.capture(tupleExpr, PlanningGraphDomain.defaultGraph());
				for (QueryOptimizer optimizer : new LmdbQueryOptimizerPipeline(strategy, tripleSource,
						store.getBackingStore().getEvaluationStatistics()).getOptimizers()) {
					optimizer.optimize(tupleExpr, null, EmptyBindingSet.getInstance());
				}
				String diagnosticPlan = diagnosticPlan(tupleExpr);
				assertTrue(tupleExpr.getDoubleMetricPlanned("plannedCostWorkRows") > 0, diagnosticPlan);
				assertThat(evaluate.apply(tupleExpr.clone())).containsExactlyInAnyOrderElementsOf(expected);
				assertTrue(containsPlannedStringMetric(tupleExpr, "optimizer.cascadesProofs",
						"packed-finite-filter-values"), diagnosticPlan);
				assertFalse(containsLeftJoin(tupleExpr), diagnosticPlan);
				assertTrue(containsExists(tupleExpr), diagnosticPlan);
				assertFalse(diagnosticPlan.contains("handledBy"), diagnosticPlan);
				assertTrue(containsPlannedStringMetric(tupleExpr, "optimizer.cascadesProofs",
						"rule=lmdb-materialized-exists-semi"), diagnosticPlan);
				assertTrue(containsPlannedStringMetric(tupleExpr, "optimizer.cascadesProofs", "materializedExists"),
						diagnosticPlan);
				assertFalse(containsPlannedStringMetric(tupleExpr, "optimizer.semanticRewrite",
						"lmdb-distinct-exists-join"), diagnosticPlan);
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void lmdbCascadesPushesFiniteMembershipBelowMinusBeforeMaterializedExists(@TempDir File dataDir) throws Exception {
		ValueStore valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig());
		try {
			TripleSource tripleSource = new EmptyTripleSource();
			StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(tripleSource, null);
			TupleExpr tupleExpr = parseTupleExpr("""
					SELECT (COUNT(DISTINCT ?requirement) AS ?count) WHERE {
					  ?requirement a <http://example.com/theme/engineering/Requirement> .
					  MINUS {
					    ?requirement <http://example.com/theme/engineering/verifiedBy> ?test .
					    ?test <http://example.com/theme/engineering/verifiedBy> ?measurement .
					  }
					  FILTER EXISTS {
					    VALUES ?name { "REQ-1000" "REQ-1001" }
					    ?requirement <http://example.com/theme/engineering/name> ?name .
					  }
					  FILTER EXISTS {
					    ?requirement <http://example.com/theme/engineering/satisfies> ?component .
					  }
					}
					""");
			for (QueryOptimizer optimizer : new LmdbQueryOptimizerPipeline(strategy, tripleSource,
					new LmdbEvaluationStatistics(valueStore, null, null)).getOptimizers()) {
				optimizer.optimize(tupleExpr, null, EmptyBindingSet.getInstance());
			}
			String diagnosticPlan = diagnosticPlan(tupleExpr);
			assertTrue(minusProbeInputContainsExistsPredicate(tupleExpr, "http://example.com/theme/engineering/name"),
					diagnosticPlan);
			assertFalse(existsPredicateFilterWrapsMinusProbe(tupleExpr, "http://example.com/theme/engineering/name"),
					diagnosticPlan);
			assertTrue(containsPlannedStringMetric(tupleExpr, "optimizer.cascadesProofs",
					"rule=lmdb-filter-minus-left-pushdown"), diagnosticPlan);
		} finally {
			valueStore.close();
		}
	}

