	@Test
	void lmdbPipelineKeepsConservativeFilterWithoutFiniteAccessProfile() {
		TripleSource tripleSource = new EmptyTripleSource();
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(tripleSource, null);
		TupleExpr tupleExpr = parseTupleExpr("""
				SELECT * WHERE {
				  ?entity <urn:unclassified-predicate> ?candidate .
				  ?entity a <urn:unclassified-type> .
				  FILTER (?candidate IN ("alpha", "beta"))
				}
				""");
		boolean encounteredCascades = false;
		for (QueryOptimizer optimizer : new LmdbQueryOptimizerPipeline(strategy, tripleSource,
				new FixedFilterPassStatistics(0.50d)).getOptimizers()) {
			optimizer.optimize(tupleExpr, null, EmptyBindingSet.getInstance());
			if (optimizer instanceof LmdbCascadesOptimizer) {
				encounteredCascades = true;
				break;
			}
		}
		assertTrue(encounteredCascades, "The costed D3 boundary must actually be executed before finalization");
		// Generic statistics expose no physical lookup/invocation profile. Costed D3 retains the conservative filter;
		// the independent algebra-equivalent finalizer may subsequently represent its exact string terms as VALUES.
		assertFalse(containsBindingSetAssignmentFor(tupleExpr, "candidate"), tupleExpr.toString());
		assertTrue(hasLiteralFilterFor(tupleExpr, "candidate", Set.of("alpha", "beta")), tupleExpr.toString());
		StandardQueryOptimizerPipeline.getFilterInValuesOptimizer()
				.optimize(tupleExpr, null, EmptyBindingSet.getInstance());
		List<Value> anchorValues = new ArrayList<>();
		tupleExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment assignment) {
				if (assignment.getBindingNames().equals(Set.of("candidate"))) {
					assignment.getBindingSets().forEach(row -> anchorValues.add(row.getValue("candidate")));
				}
			}
		});
		assertEquals(2, anchorValues.size(), tupleExpr.toString());
		assertEquals(Set.of(SimpleValueFactory.getInstance().createLiteral("alpha"),
				SimpleValueFactory.getInstance().createLiteral("beta")), new HashSet<>(anchorValues),
				tupleExpr.toString());
		assertFalse(hasLiteralFilterFor(tupleExpr, "candidate", Set.of("alpha", "beta")), tupleExpr.toString());
	}

